export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const v = u - g * t;
  const y = Math.max(0, u * t - g * t * t / 2);
  const yTop = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (time <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t > ta && time >= T - 1e-9) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 40, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 40, w: 300, h: 370, title: 'Velocity over time', state: 'v = u - g t' }));
  o.push(sdk.axis('axis.h', { x: 60, y: 380, length: 300, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const py = 380 - y / 2.2 * 300 - 14;
  const bx = 130;
  o.push(sdk.circle('ball.toss', bx, py, 28, { role: 'output' }));
  o.push(...sdk.vector('vec.v', { x: bx + 30, y: py }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'input' }));
  o.push(...sdk.vector('vec.a', { x: bx - 30, y: py }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
  o.push(sdk.callout(bx + 60, Math.min(py, 330), ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const n = 20, pts = [], cur = [];
  for (let i = 0; i <= n; i++) { const tt = 1.8 * i / n; pts.push({ x: tt, y: sdk.clamp(u - g * tt, -5.5, 5.5) }); }
  const k = 12;
  for (let i = 0; i <= k; i++) { const tt = t * i / k; cur.push({ x: tt, y: u - g * tt }); }
  o.push(sdk.plot('plot.vt', { x: 390, y: 70, w: 235, h: 290, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: pts }, { label: 'so far', kind: 'line', points: cur.length > 1 ? cur : [{ x: 0, y: u }, { x: 0.001, y: u - g * 0.001 }] }] }));
  o.push(sdk.text('plot.vt.note', 480, 395, 'slope a = -g', { role: 'warning' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: yTop, height: y, velocity: v, acceleration: -g, force: F } };
}
